   274	int PEM_ASN1_write_bio(i2d_of_void *i2d, const char *name, BIO *bp,
   275	                       void *x, const EVP_CIPHER *enc, unsigned char *kstr,
   276	                       int klen, pem_password_cb *callback, void *u)
   277	{
   278	    EVP_CIPHER_CTX ctx;
   279	    int dsize = 0, i, j, ret = 0;
   280	    unsigned char *p, *data = NULL;
   281	    const char *objstr = NULL;
   282	    char buf[PEM_BUFSIZE];
   283	    unsigned char key[EVP_MAX_KEY_LENGTH];
   284	    unsigned char iv[EVP_MAX_IV_LENGTH];
   285	
   286	    if (enc != NULL) {
   287	        objstr = OBJ_nid2sn(EVP_CIPHER_nid(enc));
   288	        if (objstr == NULL ||
   289	            cipher_by_name(objstr) == NULL ||
   290	            EVP_CIPHER_iv_length(enc) < 8) {
   291	            OPENSSL_PUT_ERROR(PEM, PEM_R_UNSUPPORTED_CIPHER);
   292	            goto err;
   293	        }
   294	    }
   295	
   296	    if ((dsize = i2d(x, NULL)) < 0) {
   297	        OPENSSL_PUT_ERROR(PEM, ERR_R_ASN1_LIB);
   298	        dsize = 0;
   299	        goto err;
   300	    }
   301	    /* dzise + 8 bytes are needed */
   302	    /* actually it needs the cipher block size extra... */
   303	    data = (unsigned char *)OPENSSL_malloc((unsigned int)dsize + 20);
   304	    if (data == NULL) {
   305	        OPENSSL_PUT_ERROR(PEM, ERR_R_MALLOC_FAILURE);
   306	        goto err;
   307	    }
   308	    p = data;
   309	    i = i2d(x, &p);
   310	
   311	    if (enc != NULL) {
   312	        const unsigned iv_len = EVP_CIPHER_iv_length(enc);
   313	
   314	        if (kstr == NULL) {
   315	            klen = 0;
   316	            if (!callback)
   317	                callback = PEM_def_callback;
   318	            klen = (*callback) (buf, PEM_BUFSIZE, 1, u);
   319	            if (klen <= 0) {
   320	                OPENSSL_PUT_ERROR(PEM, PEM_R_READ_KEY);
   321	                goto err;
   322	            }
   323	            kstr = (unsigned char *)buf;
   324	        }
   325	        assert(iv_len <= (int)sizeof(iv));
   326	        if (!RAND_bytes(iv, iv_len)) /* Generate a salt */
   327	            goto err;
   328	        /*
   329	         * The 'iv' is used as the iv and as a salt.  It is NOT taken from
   330	         * the BytesToKey function
   331	         */
   332	        if (!EVP_BytesToKey(enc, EVP_md5(), iv, kstr, klen, 1, key, NULL))
   333	            goto err;
   334	
   335	        if (kstr == (unsigned char *)buf)
   336	            OPENSSL_cleanse(buf, PEM_BUFSIZE);
   337	
   338	        assert(strlen(objstr) + 23 + 2 * iv_len + 13 <= sizeof buf);
   339	
   340	        buf[0] = '\0';
   341	        PEM_proc_type(buf, PEM_TYPE_ENCRYPTED);
   342	        PEM_dek_info(buf, objstr, iv_len, (char *)iv);
   343	        /* k=strlen(buf); */
   344	
   345	        EVP_CIPHER_CTX_init(&ctx);
   346	        ret = 1;
   347	        if (!EVP_EncryptInit_ex(&ctx, enc, NULL, key, iv)
   348	            || !EVP_EncryptUpdate(&ctx, data, &j, data, i)
   349	            || !EVP_EncryptFinal_ex(&ctx, &(data[j]), &i))
   350	            ret = 0;
   351	        else
   352	            i += j;
   353	        EVP_CIPHER_CTX_cleanup(&ctx);
   354	        if (ret == 0)
   355	            goto err;
   356	    } else {
   357	        ret = 1;
   358	        buf[0] = '\0';
   359	    }
   360	    i = PEM_write_bio(bp, name, buf, data, i);
   361	    if (i <= 0)
   362	        ret = 0;
   363	 err:
   364	    OPENSSL_cleanse(key, sizeof(key));
   365	    OPENSSL_cleanse(iv, sizeof(iv));
   366	    OPENSSL_cleanse((char *)&ctx, sizeof(ctx));
   367	    OPENSSL_cleanse(buf, PEM_BUFSIZE);
   368	    OPENSSL_free(data);
   369	    return (ret);
   370	}
